-- One atomic D1 batch. Additive tables, no rewrite of historical financial data.
CREATE TABLE CheckoutFirstWindow (
 orderId TEXT PRIMARY KEY NOT NULL REFERENCES CheckoutOrder(id) ON DELETE RESTRICT,
 checkoutGroupId TEXT NOT NULL UNIQUE REFERENCES CheckoutGroup(id) ON DELETE RESTRICT,
 createdAt INTEGER NOT NULL CHECK(typeof(createdAt)='integer' AND createdAt>=0),
 expiresAt INTEGER NOT NULL CHECK(typeof(expiresAt)='integer' AND expiresAt=createdAt+86400000)
);
CREATE TABLE CheckoutFirstExtension (
 orderId TEXT PRIMARY KEY NOT NULL REFERENCES CheckoutFirstWindow(orderId) ON DELETE RESTRICT,
 paymentId TEXT NOT NULL UNIQUE REFERENCES CheckoutPayment(id) ON DELETE RESTRICT,
 createdBy TEXT NOT NULL REFERENCES User(id) ON DELETE RESTRICT,
 decisionAt INTEGER NOT NULL CHECK(typeof(decisionAt)='integer'),
 expiresAt INTEGER NOT NULL CHECK(typeof(expiresAt)='integer' AND expiresAt=decisionAt+7200000)
);
CREATE TABLE PromoReservation (
 id TEXT PRIMARY KEY NOT NULL,
 promoCodeId TEXT NOT NULL REFERENCES PromoCodePolicy(promoCodeId) ON DELETE RESTRICT,
 checkoutGroupId TEXT NOT NULL UNIQUE REFERENCES CheckoutGroup(id) ON DELETE RESTRICT,
 orderId TEXT NOT NULL UNIQUE REFERENCES CheckoutFirstWindow(orderId) ON DELETE RESTRICT,
 userId TEXT NOT NULL REFERENCES User(id) ON DELETE RESTRICT,
 discountAmount INTEGER NOT NULL CHECK(typeof(discountAmount)='integer' AND discountAmount BETWEEN 1 AND 2147483647),
 policySnapshot TEXT NOT NULL CHECK(json_valid(policySnapshot) AND json_type(policySnapshot)='object' AND length(CAST(policySnapshot AS BLOB))<=262144),
 createdAt INTEGER NOT NULL CHECK(typeof(createdAt)='integer')
);
CREATE INDEX PromoReservation_quota ON PromoReservation(promoCodeId,userId);
CREATE TABLE PromoReservationEvent (
 id TEXT PRIMARY KEY NOT NULL,
 reservationId TEXT NOT NULL REFERENCES PromoReservation(id) ON DELETE RESTRICT,
 kind TEXT NOT NULL CHECK(kind IN('RESERVED','CONSUMED','RELEASED')),
 actorId TEXT NOT NULL REFERENCES User(id) ON DELETE RESTRICT,
 createdAt INTEGER NOT NULL CHECK(typeof(createdAt)='integer'),
 paymentLedgerId TEXT UNIQUE REFERENCES CheckoutPaymentLedger(id) ON DELETE RESTRICT,
 cancellationId TEXT UNIQUE REFERENCES CheckoutCancellation(id) ON DELETE RESTRICT,
 UNIQUE(reservationId,kind),
 CHECK((kind='RESERVED' AND paymentLedgerId IS NULL AND cancellationId IS NULL) OR (kind='CONSUMED' AND paymentLedgerId IS NOT NULL AND cancellationId IS NULL) OR (kind='RELEASED' AND paymentLedgerId IS NULL AND cancellationId IS NOT NULL))
);
CREATE UNIQUE INDEX PromoReservationEvent_terminal ON PromoReservationEvent(reservationId) WHERE kind IN('CONSUMED','RELEASED');
CREATE TRIGGER CheckoutFirstWindow_insert BEFORE INSERT ON CheckoutFirstWindow BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM CheckoutOrder o JOIN CheckoutGroup g ON g.id=o.checkoutGroupId WHERE o.id=NEW.orderId AND g.id=NEW.checkoutGroupId AND g.sealed=0 AND g.selectedSaleMode=o.saleMode AND g.createdAt=NEW.createdAt AND o.goodsTotal>0 AND o.firstPaymentAmount>0) THEN RAISE(ABORT,'invalid FIRST window contract') END; END;
CREATE TRIGGER CheckoutPayment_first_window BEFORE INSERT ON CheckoutPayment WHEN NEW.phase='FIRST' AND EXISTS(SELECT 1 FROM CheckoutFirstWindow WHERE orderId=NEW.orderId) BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM CheckoutPayment WHERE orderId=NEW.orderId AND phase='FIRST')>=3 THEN RAISE(ABORT,'FIRST maximum three accepted submissions') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM CheckoutFirstWindow w LEFT JOIN CheckoutFirstExtension x ON x.orderId=w.orderId WHERE w.orderId=NEW.orderId AND NEW.submittedAt>=w.createdAt AND NEW.submittedAt<COALESCE(x.expiresAt,w.expiresAt)) THEN RAISE(ABORT,'FIRST payment window closed') END; END;
CREATE TRIGGER CheckoutFirstExtension_insert BEFORE INSERT ON CheckoutFirstExtension BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM CheckoutPayment p JOIN CheckoutFirstWindow w ON w.orderId=p.orderId JOIN User u ON u.id=p.reviewedBy JOIN TelegramAdmin a ON a.telegramId=CAST(u.telegramId AS TEXT) WHERE p.id=NEW.paymentId AND p.orderId=NEW.orderId AND p.phase='FIRST' AND p.status='REJECTED' AND p.reviewedBy=NEW.createdBy AND p.reviewedAt=NEW.decisionAt AND NEW.decisionAt>=w.expiresAt AND p.submittedAt>=w.createdAt AND p.submittedAt<w.expiresAt AND u.status='ACTIVE' AND a.isActive=1) THEN RAISE(ABORT,'extension requires timely rejected FIRST and active reviewer') END; END;
CREATE TRIGGER CheckoutPayment_first_extension AFTER UPDATE OF status ON CheckoutPayment WHEN OLD.status='SUBMITTED' AND NEW.status='REJECTED' AND NEW.phase='FIRST' AND EXISTS(SELECT 1 FROM CheckoutFirstWindow WHERE orderId=NEW.orderId AND NEW.reviewedAt>=expiresAt) AND NOT EXISTS(SELECT 1 FROM CheckoutFirstExtension WHERE orderId=NEW.orderId) BEGIN INSERT INTO CheckoutFirstExtension(orderId,paymentId,createdBy,decisionAt,expiresAt) VALUES(NEW.orderId,NEW.id,NEW.reviewedBy,NEW.reviewedAt,NEW.reviewedAt+7200000); END;
CREATE TRIGGER CheckoutFirstExtension_audit AFTER INSERT ON CheckoutFirstExtension BEGIN INSERT INTO AuditLog(id,actorId,action,entityType,entityId,metadata,createdAt) VALUES('first-extension:'||NEW.orderId,NEW.createdBy,'first-window.extended','CheckoutFirstWindow',NEW.orderId,json_object('paymentId',NEW.paymentId,'decisionAt',NEW.decisionAt,'expiresAt',NEW.expiresAt),NEW.decisionAt); END;
CREATE TRIGGER PromoReservation_insert BEFORE INSERT ON PromoReservation BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM PromoCode p JOIN PromoCodePolicy c ON c.promoCodeId=p.id JOIN CheckoutGroup g ON g.id=NEW.checkoutGroupId JOIN CheckoutFirstWindow w ON w.checkoutGroupId=g.id JOIN CheckoutOrder o ON o.id=w.orderId WHERE p.id=NEW.promoCodeId AND p.engineVersion=2 AND p.isActive=1 AND c.sealed=1 AND (p.startsAt IS NULL OR NEW.createdAt>=p.startsAt) AND (p.endsAt IS NULL OR NEW.createdAt<p.endsAt) AND g.userId=NEW.userId AND g.sealed=0 AND g.createdAt=NEW.createdAt AND o.id=NEW.orderId AND o.saleMode=g.selectedSaleMode AND (c.saleModes='BOTH' OR c.saleModes=o.saleMode) AND (c.audience<>'PERSONAL' OR c.personalUserId=NEW.userId) AND g.discountAmount=NEW.discountAmount AND g.goodsTotal>0 AND o.firstPaymentAmount>0 AND COALESCE(json_extract(NEW.policySnapshot,'$.version')=2 AND json_extract(NEW.policySnapshot,'$.config.code')=p.code AND json_extract(NEW.policySnapshot,'$.config.type')=p.type AND json_extract(NEW.policySnapshot,'$.config.value')=p.value AND json_extract(NEW.policySnapshot,'$.quote.discountAmount')=NEW.discountAmount AND json_extract(NEW.policySnapshot,'$.quote.subtotal')=g.goodsSubtotal AND json_extract(NEW.policySnapshot,'$.quote.total')=g.goodsTotal AND json_extract(NEW.policySnapshot,'$.quote.eligibleSubtotal') BETWEEN 1 AND g.goodsSubtotal AND NEW.discountAmount<=CAST(json_extract(NEW.policySnapshot,'$.quote.eligibleSubtotal') AS INTEGER)*99/100,0)) OR EXISTS(SELECT 1 FROM CheckoutPromoUse WHERE checkoutGroupId=NEW.checkoutGroupId) THEN RAISE(ABORT,'invalid v2 promo reservation contract') END; SELECT CASE WHEN EXISTS(SELECT 1 FROM PromoCode p WHERE p.id=NEW.promoCodeId AND ((p.usageLimit IS NOT NULL AND (SELECT COUNT(*) FROM PromoCodeRedemption WHERE promoCodeId=p.id AND releasedAt IS NULL)+(SELECT COUNT(*) FROM CheckoutPromoUse WHERE promoCodeId=p.id AND releasedAt IS NULL)+(SELECT COUNT(*) FROM PromoReservation r WHERE r.promoCodeId=p.id AND NOT EXISTS(SELECT 1 FROM PromoReservationEvent e WHERE e.reservationId=r.id AND e.kind='RELEASED'))>=p.usageLimit) OR (SELECT COUNT(*) FROM PromoCodeRedemption WHERE promoCodeId=p.id AND userId=NEW.userId AND releasedAt IS NULL)+(SELECT COUNT(*) FROM CheckoutPromoUse WHERE promoCodeId=p.id AND userId=NEW.userId AND releasedAt IS NULL)+(SELECT COUNT(*) FROM PromoReservation r WHERE r.promoCodeId=p.id AND r.userId=NEW.userId AND NOT EXISTS(SELECT 1 FROM PromoReservationEvent e WHERE e.reservationId=r.id AND e.kind='RELEASED'))>=p.perUserLimit)) THEN RAISE(ABORT,'v2 promo reservation quota exhausted') END; END;
CREATE TRIGGER CheckoutPromoUse_reservation_isolated BEFORE INSERT ON CheckoutPromoUse WHEN EXISTS(SELECT 1 FROM PromoReservation WHERE checkoutGroupId=NEW.checkoutGroupId) BEGIN SELECT RAISE(ABORT,'one promo per checkout group'); END;
CREATE TRIGGER PromoReservationEvent_insert BEFORE INSERT ON PromoReservationEvent BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM PromoReservation WHERE id=NEW.reservationId AND NEW.createdAt>=createdAt) THEN RAISE(ABORT,'invalid promo event time') END; SELECT CASE WHEN NEW.kind='RESERVED' AND (EXISTS(SELECT 1 FROM PromoReservationEvent WHERE reservationId=NEW.reservationId) OR NOT EXISTS(SELECT 1 FROM PromoReservation r JOIN CheckoutGroup g ON g.id=r.checkoutGroupId WHERE r.id=NEW.reservationId AND r.userId=NEW.actorId AND r.createdAt=NEW.createdAt AND g.sealed=0)) THEN RAISE(ABORT,'invalid initial reservation event') END; SELECT CASE WHEN NEW.kind IN('CONSUMED','RELEASED') AND (NOT EXISTS(SELECT 1 FROM PromoReservationEvent WHERE reservationId=NEW.reservationId AND kind='RESERVED') OR EXISTS(SELECT 1 FROM PromoReservationEvent WHERE reservationId=NEW.reservationId AND kind IN('CONSUMED','RELEASED'))) THEN RAISE(ABORT,'promo reservation already terminal') END; SELECT CASE WHEN NEW.kind='CONSUMED' AND NOT EXISTS(SELECT 1 FROM PromoReservation r JOIN CheckoutPaymentLedger l ON l.orderId=r.orderId JOIN CheckoutGroup g ON g.id=r.checkoutGroupId WHERE r.id=NEW.reservationId AND l.id=NEW.paymentLedgerId AND l.phase='FIRST' AND l.verifiedBy=NEW.actorId AND l.verifiedAt=NEW.createdAt AND g.sealed=1) THEN RAISE(ABORT,'consumption requires confirmed FIRST ledger') END; SELECT CASE WHEN NEW.kind='RELEASED' AND (NOT EXISTS(SELECT 1 FROM PromoReservation r JOIN CheckoutCancellation c ON c.orderId=r.orderId WHERE r.id=NEW.reservationId AND c.id=NEW.cancellationId AND c.sealed=1 AND c.createdBy=NEW.actorId AND c.createdAt=NEW.createdAt) OR EXISTS(SELECT 1 FROM PromoReservation r JOIN CheckoutPaymentLedger l ON l.orderId=r.orderId WHERE r.id=NEW.reservationId) OR EXISTS(SELECT 1 FROM PromoReservation r JOIN CheckoutPayment p ON p.orderId=r.orderId WHERE r.id=NEW.reservationId AND p.status IN('SUBMITTED','APPROVED'))) THEN RAISE(ABORT,'release requires sealed unpaid cancellation without pending receipt') END; END;
CREATE TRIGGER PromoReservationEvent_audit AFTER INSERT ON PromoReservationEvent BEGIN INSERT INTO AuditLog(id,actorId,action,entityType,entityId,metadata,createdAt) VALUES('promo-event:'||NEW.id,NEW.actorId,CASE NEW.kind WHEN 'RESERVED' THEN 'promo.reserved' WHEN 'CONSUMED' THEN 'promo.consumed' ELSE 'promo.released' END,'PromoReservation',NEW.reservationId,json_object('kind',NEW.kind,'paymentLedgerId',NEW.paymentLedgerId,'cancellationId',NEW.cancellationId),NEW.createdAt); END;
CREATE TRIGGER PromoReservation_initial AFTER INSERT ON PromoReservation BEGIN INSERT INTO PromoReservationEvent(id,reservationId,kind,actorId,createdAt) VALUES('reserved:'||NEW.id,NEW.id,'RESERVED',NEW.userId,NEW.createdAt); END;
CREATE TRIGGER CheckoutPaymentLedger_promo_consume AFTER INSERT ON CheckoutPaymentLedger WHEN NEW.phase='FIRST' BEGIN INSERT INTO PromoReservationEvent(id,reservationId,kind,actorId,createdAt,paymentLedgerId) SELECT 'consumed:'||id,id,'CONSUMED',NEW.verifiedBy,NEW.verifiedAt,NEW.id FROM PromoReservation WHERE orderId=NEW.orderId; END;
CREATE TRIGGER CheckoutCancellation_promo_release AFTER UPDATE OF sealed ON CheckoutCancellation WHEN OLD.sealed=0 AND NEW.sealed=1 BEGIN INSERT INTO PromoReservationEvent(id,reservationId,kind,actorId,createdAt,cancellationId) SELECT 'released:'||id,id,'RELEASED',NEW.createdBy,NEW.createdAt,NEW.id FROM PromoReservation WHERE orderId=NEW.orderId; END;
CREATE VIEW PromoReservationState AS SELECT r.*,CASE WHEN EXISTS(SELECT 1 FROM PromoReservationEvent e WHERE e.reservationId=r.id AND kind='CONSUMED') THEN 'CONSUMED' WHEN EXISTS(SELECT 1 FROM PromoReservationEvent e WHERE e.reservationId=r.id AND kind='RELEASED') THEN 'RELEASED' ELSE 'RESERVED' END state FROM PromoReservation r;
CREATE TRIGGER CheckoutFirstWindow_immutable_UPDATE BEFORE UPDATE ON CheckoutFirstWindow BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER CheckoutFirstWindow_immutable_DELETE BEFORE DELETE ON CheckoutFirstWindow BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER revision_CheckoutFirstWindow_INSERT AFTER INSERT ON CheckoutFirstWindow BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutFirstWindow_UPDATE AFTER UPDATE ON CheckoutFirstWindow BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutFirstWindow_DELETE AFTER DELETE ON CheckoutFirstWindow BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER CheckoutFirstExtension_immutable_UPDATE BEFORE UPDATE ON CheckoutFirstExtension BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER CheckoutFirstExtension_immutable_DELETE BEFORE DELETE ON CheckoutFirstExtension BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER revision_CheckoutFirstExtension_INSERT AFTER INSERT ON CheckoutFirstExtension BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutFirstExtension_UPDATE AFTER UPDATE ON CheckoutFirstExtension BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_CheckoutFirstExtension_DELETE AFTER DELETE ON CheckoutFirstExtension BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER PromoReservation_immutable_UPDATE BEFORE UPDATE ON PromoReservation BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER PromoReservation_immutable_DELETE BEFORE DELETE ON PromoReservation BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER revision_PromoReservation_INSERT AFTER INSERT ON PromoReservation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_PromoReservation_UPDATE AFTER UPDATE ON PromoReservation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_PromoReservation_DELETE AFTER DELETE ON PromoReservation BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER PromoReservationEvent_immutable_UPDATE BEFORE UPDATE ON PromoReservationEvent BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER PromoReservationEvent_immutable_DELETE BEFORE DELETE ON PromoReservationEvent BEGIN SELECT RAISE(ABORT,'promo lifecycle history immutable'); END;
CREATE TRIGGER revision_PromoReservationEvent_INSERT AFTER INSERT ON PromoReservationEvent BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_PromoReservationEvent_UPDATE AFTER UPDATE ON PromoReservationEvent BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
CREATE TRIGGER revision_PromoReservationEvent_DELETE AFTER DELETE ON PromoReservationEvent BEGIN UPDATE _Revision SET version=version+1 WHERE id=1; END;
-- Preserve every historical group invariant, with a separate immutable v2 discount source.
DROP TRIGGER CheckoutGroup_seal;
CREATE TRIGGER CheckoutGroup_seal BEFORE UPDATE ON CheckoutGroup WHEN OLD.sealed=0 BEGIN  SELECT CASE WHEN NEW.id<>OLD.id OR NEW.userId<>OLD.userId OR NEW.idempotencyKey<>OLD.idempotencyKey OR NEW.requestFingerprint<>OLD.requestFingerprint OR NEW.recipient<>OLD.recipient OR NEW.goodsSubtotal<>OLD.goodsSubtotal OR NEW.discountAmount<>OLD.discountAmount OR NEW.goodsTotal<>OLD.goodsTotal OR NEW.createdAt<>OLD.createdAt OR NEW.sealed<>1 THEN RAISE(ABORT,'invalid group seal') END;  SELECT CASE WHEN (SELECT COUNT(*) FROM CheckoutOrder WHERE checkoutGroupId=OLD.id) NOT BETWEEN 1 AND 2 THEN RAISE(ABORT,'incomplete group') END;  SELECT CASE WHEN (SELECT SUM(goodsSubtotal) FROM CheckoutOrder WHERE checkoutGroupId=OLD.id)<>OLD.goodsSubtotal OR (SELECT SUM(discountAmount) FROM CheckoutOrder WHERE checkoutGroupId=OLD.id)<>OLD.discountAmount OR (SELECT SUM(goodsTotal) FROM CheckoutOrder WHERE checkoutGroupId=OLD.id)<>OLD.goodsTotal THEN RAISE(ABORT,'group money mismatch') END;  SELECT CASE WHEN EXISTS(SELECT 1 FROM CheckoutOrder o WHERE o.checkoutGroupId=OLD.id AND ((SELECT COUNT(*) FROM CheckoutOrderItem i WHERE i.orderId=o.id)=0 OR (SELECT SUM(lineTotal) FROM CheckoutOrderItem i WHERE i.orderId=o.id)<>o.goodsSubtotal)) THEN RAISE(ABORT,'incomplete order items') END;  SELECT CASE WHEN OLD.discountAmount>0 AND COALESCE((SELECT discountAmount FROM CheckoutPromoUse WHERE checkoutGroupId=OLD.id),(SELECT discountAmount FROM PromoReservation WHERE checkoutGroupId=OLD.id),0)<>OLD.discountAmount THEN RAISE(ABORT,'missing group promotion') END; END;
CREATE TRIGGER CheckoutGroup_reservation_seal BEFORE UPDATE OF sealed ON CheckoutGroup WHEN NEW.sealed=1 BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM PromoReservation r WHERE r.checkoutGroupId=OLD.id AND (NOT EXISTS(SELECT 1 FROM PromoReservationEvent e WHERE e.reservationId=r.id AND e.kind='RESERVED') OR EXISTS(SELECT 1 FROM CheckoutPromoUse WHERE checkoutGroupId=OLD.id))) THEN RAISE(ABORT,'incomplete or duplicate reservation promotion') END; END;
UPDATE _Revision SET version=version+1 WHERE id=1;
